	if err != nil {
		return nil, fmt.Errorf("invalid post id: %s", input.PostID)
	}

	post, err := r.GetPostByIDUseCase.Execute(ctx, numericPostID)
	if err != nil {
		return nil, fmt.Errorf("post not found with id: %s", input.PostID)
	}

